def transform(grid):
    """Replace monochrome rectangles at least 4 rows by 5 columns with color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for top in range(h - 3):
        for color in set(grid[top]):
            valid = [True] * w
            for bottom in range(top, h):
                valid = [valid[c] and grid[bottom][c] == color for c in range(w)]
                if bottom - top + 1 < 4:
                    continue
                c = 0
                while c < w:
                    if not valid[c]:
                        c += 1
                        continue
                    start = c
                    while c < w and valid[c]:
                        c += 1
                    if c - start >= 5:
                        for r in range(top, bottom + 1):
                            for x in range(start, c):
                                out[r][x] = 4
    return out
